INSERT INTO products (name, description, category_id, price, discount_percent, stock, image_url, active)
SELECT s.name, s.description, c.id, s.price, s.discount_percent, s.stock, s.image_url, TRUE
FROM seed s
JOIN categories c ON c.name = s.category_name
WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.name = s.name);
